namespace ghidra.framework.task.gui.taskview;






using generic.theme.GThemeDefaults;
using ghidra.util.layout;

// This component is basically a JPanel that implements the Scrollable interface needed for the 
// TaskViewer.
public class TaskViewerComponent : JPanel, Scrollable {
	private static readonly int PREFERRED_WIDTH = 400;
	private static readonly int PREFERRED_HEIGHT = 500;
	private static readonly int UNIT_SCROLL = 30;

	public TaskViewerComponent() : base(new VerticalLayout(0))
    {
		setBackground(Colors.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(20, 20, 20, 20));
	}

	/* @Override */
	public Dimension getPreferredScrollableViewportSize() {
		return new Dimension(PREFERRED_WIDTH, PREFERRED_HEIGHT);
	}

	/* @Override */
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
		return UNIT_SCROLL;
	}

	/* @Override */
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
		return UNIT_SCROLL * 5;
	}

	/* @Override */
	public bool getScrollableTracksViewportWidth() {
		return true;
	}

	/* @Override */
	public bool getScrollableTracksViewportHeight() {
		return false;
	}

}
